<script setup lang="ts">
import { capturedResourcePath } from '../quick-capture.meta'; import type { CreatedResourceReference } from '../quick-capture.types'
const emit = defineEmits<{ dirty: [value: boolean]; pending: [value: boolean]; created: [value: CreatedResourceReference] }>(); const api = useApi(); const toast = useToast(); const state = reactive({ title: '', description: '', externalUrl: '', difficulty: 'Medium', topics: '' }); const pending = ref(false); const errors = ref<Record<string, string[]>>({}); const formError = ref('')
watch(state, () => emit('dirty', Boolean(state.title || state.description || state.externalUrl || state.topics)), { deep: true })
async function submit() { if (pending.value) return; if (!state.title.trim() || !state.description.trim()) { errors.value = { ...(!state.title.trim() && { title: ['Title is required.'] }), ...(!state.description.trim() && { description: ['Description is required.'] }) }; return } pending.value = true; emit('pending', true); try { const created = await api.post<{ id: string; title: string }>('/dsa-problems', { title: state.title.trim(), description: state.description.trim(), difficulty: state.difficulty, source: null, externalUrl: state.externalUrl.trim() || null, topics: state.topics.split(',').map(x => x.trim()).filter(Boolean) }); toast.add({ title: 'DSA problem added', color: 'success' }); emit('created', { id: created.id, title: created.title, targetPath: capturedResourcePath('DsaProblem', created.id) }) } catch (error) { const normalized = normalizeApiError(error); errors.value = normalized.fieldErrors; formError.value = normalized.detail ?? normalized.title } finally { pending.value = false; emit('pending', false) } }
</script>
<template><form class="grid gap-4" @submit.prevent="submit"><UFormField label="Title" required :error="errors.title?.[0]"><UInput v-model="state.title" autofocus class="w-full" /></UFormField><UFormField label="Description" required :error="errors.description?.[0]"><UTextarea v-model="state.description" :rows="4" class="w-full" /></UFormField><UFormField label="Problem URL" :error="errors.externalUrl?.[0]"><UInput v-model="state.externalUrl" type="url" class="w-full" /></UFormField><UFormField label="Difficulty"><select v-model="state.difficulty" class="w-full rounded-md border border-default bg-default p-2"><option>Easy</option><option>Medium</option><option>Hard</option></select></UFormField><UFormField label="Topics" hint="Comma-separated"><UInput v-model="state.topics" class="w-full" /></UFormField><p v-if="formError" role="alert" class="text-sm text-error">{{ formError }}</p><UButton type="submit" label="Add problem" block :loading="pending" :disabled="pending" /></form></template>
